<script setup lang="ts">
import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import {create} from '../api/estimates';import {useAsync} from '../hooks/useAsync';import {number} from '../utils/format';
const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();
const name=ref(''),estimateId=ref(''),datasetId=ref(''),text=ref('');
const active=computed(()=>props.data.estimates.find(e=>e.id===estimateId.value)||props.data.estimates[0]);
const activeDataset=computed(()=>props.data.datasets.find(d=>d.id===active.value?.dataset_id));
const ds=computed(()=>props.data.datasets.find(d=>d.id===datasetId.value)||props.data.datasets[0]);
const {busy,error,execute}=useAsync();
function draft(){const d=ds.value;if(!d){text.value='';return}const rows=d.alternatives.map(a=>{const values:Record<string,{min:number;mode:number;max:number}>={};for(const c of d.columns){const v=a.values[c.code];const span=Math.abs(v)*.15||1;values[c.code]={min:Number((v-span).toFixed(2)),mode:v,max:Number((v+span).toFixed(2))}}return {alternative_id:a.alternative_id,values}});text.value=JSON.stringify(rows,null,1)}
async function submit(){await execute(async()=>{await create({name:name.value,dataset_id:ds.value?.id,ranges:JSON.parse(text.value)});name.value='';await props.refresh()})};
</script>
<template>
<PageHeading code="05 / INTERVAL ESTIMATES" title="指标不是定值，就先把区间写明。" description="每条航段的每项指标填写下限、最可能值和上限，按三角分布独立抽样；权重固定，每次重算全体航段的归一化与理想点。"/>
<section class="paper"><div class="section-heading"><h2>航段指标区间</h2><select aria-label="选择区间估计" :value="active?.id" @change="estimateId=($event.target as HTMLSelectElement).value"><option v-for="e in data.estimates" :key="e.id" :value="e.id">{{e.name}}</option></select></div><template v-if="active"><div class="data-caption"><b>{{active.ranges.length}}条航段</b><span>{{activeDataset?.name}}</span><span>{{active.created_at.slice(0,10)}}</span></div><div class="table-scroll"><table><thead><tr><th>航段</th><th v-for="c in activeDataset?.columns" :key="c.code">{{c.label}}<small>{{c.unit}} · 下 / 最可能 / 上</small></th></tr></thead><tbody><tr v-for="r in active.ranges" :key="r.alternative_id"><td><b>{{activeDataset?.alternatives.find(a=>a.alternative_id===r.alternative_id)?.name}}</b><small>{{r.alternative_id}}</small></td><td v-for="c in activeDataset?.columns" :key="c.code">{{number(r.values[c.code]?.min,2)}} / {{number(r.values[c.code]?.mode,2)}} / {{number(r.values[c.code]?.max,2)}}</td></tr></tbody></table></div></template><Empty v-else>先导入方案集，再为每条航段的每项指标填写下限、最可能值和上限。</Empty></section>
<section class="paper" v-if="canWrite"><h2>导入区间估计</h2><form class="grid-form" @submit.prevent="submit"><label>区间名称<input aria-label="区间名称" required minlength="2" v-model="name"/></label><label>方案集<select aria-label="区间方案集" :value="ds?.id" @change="datasetId=($event.target as HTMLSelectElement).value"><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></label><div class="wide matrix-help"><span>每条航段一行，须覆盖该方案集的全部指标；下限≤最可能值≤上限。抽样在“排序与敏感性”页指定样本量和随机种子。</span><button type="button" class="text-button" @click="draft">按方案值±15%填入初稿</button></div><label class="wide">区间JSON数组<textarea aria-label="区间JSON" rows="6" required v-model="text" placeholder='[{"alternative_id":"YZ-01","values":{"cost":{"min":16,"mode":19,"max":22}, …}}]'/></label><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">核查并保存区间</button></form></section>
</template>
